(function(){
  var Reg = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
  var RL = Java.loadClass('net.minecraft.resources.ResourceLocation');
  var mc = Java.loadClass('net.minecraft.client.Minecraft').getInstance();
  if (mc.level === null) { throw new Error('端点: client 侧 level 为空（客户端未进入世界）'); }
  var reg = Reg.PARTICLE_TYPE;
  var tG = reg.get(RL.parse('astral_dice:glowing_dust'));
  var tL = reg.get(RL.parse('astral_dice:particle_library'));
  var rm = mc.getResourceManager();
  return {
    glowingRegistered: tG !== null,
    libraryRegistered: tL !== null,
    registeredCount: (tG !== null ? 1 : 0) + (tL !== null ? 1 : 0),
    particleJsonGlowing: rm.getResource(RL.parse('astral_dice:particles/glowing_dust.json')).isPresent(),
    particleJsonLibrary: rm.getResource(RL.parse('astral_dice:particles/particle_library.json')).isPresent()
  };
})()
